<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">cat</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /proc/stat</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">             # CPU time: user/system/idle/iowait, etc.</span></span>
